function validate([root]) {
  if (!Array.isArray(root)) return 'root must be a level-order array.';
  if (root.length > 0 && root[0] === null) return 'Write an empty tree as [].';
  let count = 0;
  let open = 1;
  for (const item of root) {
    if (open === 0) return 'Every node after the root needs a parent.';
    if (item === null) {
      open--;
      continue;
    }
    if (!Array.isArray(item) || item.length !== 2) return 'Write each node as [val, randomIndex].';
    const [val, index] = item;
    if (!Number.isInteger(val) || val < 1 || val > 1000000) return 'Each node value is a whole number from 1 to 10^6.';
    if (index !== null && (!Number.isInteger(index) || index < 0 || index >= root.length || root[index] === null)) return 'randomIndex must be null or the position of a node in the array.';
    count++;
    open++;
  }
  if (count > 1000) return 'The tree has at most 1000 nodes.';
  return null;
}

