function adapt(input, solve, kit) {
  const [values] = input;
  class Node {
    constructor(val) { this.val = val; this.left = null; this.right = null; this.random = null; }
  }
  // LeetCode provides NodeCopy for the answer; this is the same class.
  class NodeCopy {
    constructor(val = 0, left = null, right = null, random = null) { this.val = val; this.left = left; this.right = right; this.random = random; }
  }
  globalThis.NodeCopy = NodeCopy;
  // slots[i] is the node written at position i of the array, or null for a gap.
  const slots = values.map(item => item === null ? null : new Node(item[0]));
  const root = slots.length > 0 ? slots[0] : null;
  const queue = root ? [root] : [];
  let next = 1;
  for (let head = 0; head < queue.length; head++) {
    for (const side of ['left', 'right']) {
      if (next < slots.length && slots[next] !== null) {
        queue[head][side] = slots[next];
        queue.push(slots[next]);
      }
      next++;
    }
  }
  values.forEach((item, i) => { if (item !== null && item[1] !== null) slots[i].random = slots[item[1]]; });
  const links = queue.map(node => [node.val, node.left, node.right, node.random]);
  const result = solve(root);
  if (result === undefined) throw new Error('The solution did not return a value.');
  const intact = queue.every((node, i) => node.val === links[i][0] && node.left === links[i][1] && node.right === links[i][2] && node.random === links[i][3]);
  if (!intact) throw new Error('The original tree must not be modified.');
  // Read the copy in level order, checking that it is a separate tree made of NodeCopy objects.
  const order = [];
  const seen = new Set();
  const walk = [result];
  for (let q = 0; q < walk.length; q++) {
    const node = walk[q];
    if (node == null) {
      order.push(null);
      continue;
    }
    if (!(node instanceof NodeCopy)) throw new Error('Build the copy from new NodeCopy objects; it must not reuse original nodes.');
    if (seen.has(node) || seen.size > 2000) throw new Error('The copy must be a tree: no node may be reached twice through left and right.');
    seen.add(node);
    order.push(node);
    walk.push(node.left, node.right);
  }
  while (order.length > 0 && order[order.length - 1] === null) order.pop();
  const position = new Map();
  order.forEach((node, i) => { if (node !== null) position.set(node, i); });
  return order.map(node => {
    if (node === null) return null;
    if (node.random == null) return [node.val, null];
    if (!position.has(node.random)) throw new Error('Each random link of the copy must point to a node of the copy.');
    return [node.val, position.get(node.random)];
  });
}

