function copyRandomBinaryTree(root) {
  const copies = new Map();

  function copy(node) {
    if (!node) {
      return null;
    }
    if (copies.has(node)) {
      return copies.get(node);
    }
    const clone = new NodeCopy(node.val);
    copies.set(node, clone);
    clone.left = copy(node.left);
    clone.right = copy(node.right);
    clone.random = copy(node.random);
    return clone;
  }

  return copy(root);
}

