function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const count = size === 'large' ? 900 + pick(100) : pick(11);
  if (count === 0) return [[]];
  // Small trees often repeat values, so a copy keyed by value instead of by node goes wrong.
  const top = size === 'small' && rand() < 0.5 ? 3 : 1000000;
  const value = () => 1 + pick(top);
  const deep = rand() < 0.3;
  const nodes = [{ val: value(), left: null, right: null, random: null }];
  while (nodes.length < count) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(3))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    const node = { val: value(), left: null, right: null, random: null };
    parent[side] = node;
    nodes.push(node);
  }
  const linked = rand();
  for (const node of nodes) if (rand() < linked) node.random = nodes[pick(nodes.length)];
  const order = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    order.push(node);
    if (node) queue.push(node.left, node.right);
  }
  while (order[order.length - 1] === null) order.pop();
  const position = new Map();
  order.forEach((node, i) => { if (node) position.set(node, i); });
  return [order.map(node => node ? [node.val, node.random ? position.get(node.random) : null] : null)];
}
